from ail import read_bytes, write_bytes
import sys

def main() -> int:
    try:
        limit = float(sys.argv[3])
        if limit < 0.0:
            raise ValueError
        values = []
        for word in read_bytes(sys.argv[1]).decode().split():
            values.append(float(word))
        result = clip_values(values, limit)
        release_values()
        output = []
        for value in result:
            bits = float_bits(value)
            output.append(bits % 256)
            output.append(bits // 256 % 256)
            output.append(bits // 65536 % 256)
            output.append(bits // 16777216)
        write_bytes(sys.argv[2], bytes(output))
        return 0
    except ValueError:
        print('invalid input')
        return 2
    except OSError:
        print('file error')
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
